"""Independent Python-integer oracle, rejection suite and CLI metamorphic checks."""
import copy
import itertools
import json
from pathlib import Path
import random
import subprocess
import sys

BINARY = str(Path(sys.argv[1]).resolve())
ROOT = Path(__file__).resolve().parents[1]
COUNT = 0


def call(request, valid=True, args=("score",)):
    global COUNT
    wire = request if isinstance(request, bytes) else json.dumps(request, separators=(",", ":")).encode()
    result = subprocess.run([BINARY, *args], input=wire, capture_output=True, timeout=5)
    COUNT += 1
    if not valid:
        assert result.returncode == 2 and result.stderr and not result.stdout, result
        return
    assert result.returncode == 0 and not result.stderr, result
    return json.loads(result.stdout), result.stdout


def oracle(request):
    w = request["weights"]
    entries = []
    for item in request["entries"]:
        indices = [i for i, seen in enumerate(item["mask"]) if seen]
        d = sum(w[i] for i in indices)
        s = sum(w[i] * item["trits"][i] for i in indices)
        status = "inactive" if not item["active"] else "abstain" if not d else "scored"
        entries.append(dict(id=item["id"], active=item["active"], status=status,
                            score=dict(numerator=s, denominator=d) if status == "scored" else None,
                            coverage=dict(numerator=d, denominator=sum(w)),
                            observed_count=len(indices), factor_count=len(w)))
    return dict(schema="trinite.ternary-evidence-result.v1", entries=entries)


def check(request):
    actual, raw = call(request)
    assert actual == oracle(request), (request, actual, oracle(request))
    assert call(request)[1] == raw
    return actual


def base(weights=(2, 3, 0), trits=(1, 0, -1), mask=(True, True, True)):
    return dict(schema="trinite.ternary-evidence-request.v1", input_kind="generic-public-trits",
                weights=list(weights), entries=[dict(id="item_1", active=True, trits=list(trits), mask=list(mask))])


# Frozen original synthetic examples are checked, never regenerated by this test.
fixture = json.loads((ROOT / "example-request.json").read_text())
assert check(fixture) == json.loads((ROOT / "example-result.json").read_text())
for trits in itertools.product((-1, 0, 1), repeat=3):
    for mask in itertools.product((False, True), repeat=3):
        check(base(trits=[t if seen else 0 for t, seen in zip(trits, mask)], mask=mask))

rng = random.Random(0x7E11)
for case in range(80):
    n = rng.randrange(1, 65)
    weights = [rng.randrange(0, 1_000_000_001) for _ in range(n)]
    weights[0] = 1_000_000_000
    request = base(weights=weights, trits=[0]*n, mask=[False]*n)
    request["entries"] = []
    for j in range(3):
        mask = [bool(rng.randrange(2)) for _ in range(n)]
        request["entries"].append(dict(id=f"item_{j}", active=j != 2,
            trits=[rng.choice((-1, 0, 1)) if m else 0 for m in mask], mask=mask))
    original = check(request)
    negated = copy.deepcopy(request)
    for row in negated["entries"]:
        row["trits"] = [-t for t in row["trits"]]
    opposite = check(negated)
    for a, b in zip(original["entries"], opposite["entries"]):
        assert a["coverage"] == b["coverage"]
        if a["score"]:
            assert a["score"]["numerator"] == -b["score"]["numerator"]
    perm = list(range(n)); rng.shuffle(perm)
    shuffled = copy.deepcopy(request)
    shuffled["weights"] = [weights[i] for i in perm]
    for row in shuffled["entries"]:
        for key in ("trits", "mask"):
            row[key] = [row[key][i] for i in perm]
    assert check(shuffled) == original
    shuffled["entries"].reverse()
    assert check(shuffled)["entries"] == list(reversed(original["entries"]))

# Extreme safe totals, zero observed weight, observed neutral, wholly missing.
for sign in (-1, 0, 1):
    check(base([10**9]*64, [sign]*64, [True]*64))
check(base([0, 1], [1, 0], [True, False]))
check(base([1], [0], [True]))
check(base([1], [0], [False]))
r = base([1], [0], [True]); r["entries"] *= 64
for i, row in enumerate(r["entries"]):
    r["entries"][i] = {**row, "id": f"id{i}"}
check(r)

bad = []
for key in ("seed", "ground_truth", "private_traits", "schema_typo"):
    r = base(); r[key] = 1; bad.append(r)
for key in base():
    r = base(); del r[key]; bad.append(r)
for weights in ([], [0], [-1], [10**9+1], [True], [1.0], [1]*65):
    r = base(); r["weights"] = weights; bad.append(r)
for entries in ([], [{}]*65):
    r = base(); r["entries"] = entries; bad.append(r)
for field, values in {"id": ["", "bad\"id", "a b", "a"*65, 1], "active": [1, None],
                      "trits": [[2, 0, 0], [True, 0, 0], [1], [1.0, 0, 0]],
                      "mask": [[1, 1, 1], [False], [False, True, True]]}.items():
    for value in values:
        r = base(); r["entries"][0][field] = value; bad.append(r)
r = base(); r["entries"] *= 2; bad.append(r)
r = base(); r["entries"][0]["secret"] = 1; bad.append(r)
r = base(); r["entries"][0]["active"] = False; r["entries"][0]["trits"][0] = 2; bad.append(r)
for kind in ("race-private", "generic", ""):
    r = base(); r["input_kind"] = kind; bad.append(r)
for r in bad:
    call(r, False)
wire = json.dumps(base()).encode()
for malformed in (wire + b"x", wire.replace(b'"weights":', b'"weights": [], "weights":'),
                  wire.replace(b'"active": true', b'"active": true, "active": true'),
                  wire.replace(b'2, 3, 0', b'9223372036854775808, 3, 0'),
                  wire.replace(b'2, 3, 0', b'-9223372036854775809, 3, 0'),
                  wire.replace(b'2, 3, 0', b'-0, 3, 0'), b" "*16385,
                  b"["*10+b"0"+b"]"*10, b"\xff", wire.replace(b'item_1', b'item\\u005f1')):
    call(malformed, False)
for args in ((), ("target",), ("score", "extra")):
    call(base(), False, args)
# Already closed stdout is an intentional successful early exit, not a panic.
reader, writer = __import__("os").pipe()
__import__("os").close(reader)
try:
    result = subprocess.run([BINARY, "score"], input=wire, stdout=writer, stderr=subprocess.PIPE, timeout=5)
    assert result.returncode == 0 and not result.stderr
finally:
    __import__("os").close(writer)
print(f"ternary-evidence-v1: {COUNT} independent CLI/oracle checks passed")
